package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A statement taken for a person on a sheet: their due-total at that moment (none when it was n/a),
 * the date it is as of (the sheet's today when it was taken, unless taken as of an earlier date), the
 * sheet's today when it was taken, and who took it.
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "statement_date", nullable = false)
    private LocalDate date;

    @Column(name = "taken_on")
    private LocalDate takenOn;

    @Column(name = "taken_by", nullable = false, length = 100)
    private String takenBy;

    protected Statement() {}

    public Statement(String sheetId, Long personId, BigDecimal dueTotal, LocalDate date, LocalDate takenOn,
            String takenBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.date = date;
        this.takenOn = takenOn;
        this.takenBy = takenBy;
    }

    /** A copy of the statement, as taken, for the person on the sheet. */
    public Statement copyFor(String sheetId, Long personId) {
        return new Statement(sheetId, personId, dueTotal, date, takenOn, takenBy);
    }

    /** Move the statement to the person on the sheet, as taken. */
    public void moveTo(String sheetId, Long personId) {
        this.sheetId = sheetId;
        this.personId = personId;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getDueTotal() { return dueTotal; }

    public LocalDate getDate() { return date; }

    /** The sheet's today when it was taken. */
    public LocalDate getTakenOn() { return takenOn; }

    public String getTakenBy() { return takenBy; }
}
package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class StatementController {

    /** A person's statements as the screen shows them; the last due-total has two decimals, null when n/a. */
    public record StatementSummaryView(Long personId, int count, String lastDueTotal, LocalDate lastDate) {
        static StatementSummaryView of(StatementService.Summary summary) {
            return new StatementSummaryView(summary.personId(), summary.count(),
                    summary.lastDueTotal() == null ? null : summary.lastDueTotal().setScale(2).toPlainString(),
                    summary.lastDate());
        }
    }

    /** A statement just taken: the person's statements and their claims as they now stand. */
    public record StatementTakenView(StatementSummaryView summary, List<ClaimView> claims) {}

    /** The date a statement is taken as of (blank: now). */
    public record StatementRequest(LocalDate asOf) {}

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    @GetMapping("/statements")
    public List<StatementSummaryView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.summaries(sheetId).stream().map(StatementSummaryView::of).toList();
    }

    @PostMapping("/people/{personId}/statement")
    public StatementTakenView take(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) StatementRequest request) {
        StatementService.Taken taken = service.take(sheetId, user, personId, request == null ? null : request.asOf());
        return new StatementTakenView(StatementSummaryView.of(taken.summary()),
                taken.claims().stream().map(ClaimView::of).toList());
    }

    @PostMapping("/people/{personId}/statement/cancel")
    public StatementTakenView cancel(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken taken = service.cancelLast(sheetId, user, personId);
        return new StatementTakenView(StatementSummaryView.of(taken.summary()),
                taken.claims().stream().map(ClaimView::of).toList());
    }
}
